// Config plugin: signs release builds with your own upload key instead of the debug key.
// android/ is generated by `npx expo prebuild`, so the change lives here and is
// re-applied on every prebuild. Key details come from ~/.gradle/gradle.properties.
// https://docs.expo.dev/config-plugins/introduction/
const { withAppBuildGradle } = require('expo/config-plugins');

const { addReleaseSigning } = require('./release-signing');

module.exports = function withReleaseSigning(config) {
  return withAppBuildGradle(config, (cfg) => {
    if (cfg.modResults.language !== 'groovy') {
      throw new Error('with-release-signing: expected a Groovy build.gradle');
    }
    cfg.modResults.contents = addReleaseSigning(cfg.modResults.contents);
    return cfg;
  });
};
